engine.analyze:
async function analyze(input, providers) {
  var tools = (await providers.tools.list()) || [];
  var dataBundles = providers.tools.listData ? (await providers.tools.listData()) || [] : [];
  var user = providers.tools.userIdentity ? providers.tools.userIdentity() : {};

  var visibleTools = tools.filter(function (t) {
    if (!t || !t.id) return false;
    if (String(t.id).charAt(0) === "_") return false;
    if (providers.tools.matchesAudience && !providers.tools.matchesAudience(t, user)) return false;
    return true;
  });

  visibleTools.sort(function (a, b) {
    var ca = (a.catalog && a.catalog.category) || "Other";
    var cb = (b.catalog && b.catalog.category) || "Other";
    if (ca !== cb) return String(ca).localeCompare(String(cb));
    var oa = (a.catalog && a.catalog.order) || 999;
    var ob = (b.catalog && b.catalog.order) || 999;
    if (oa !== ob) return oa - ob;
    return String(a.label || a.id).localeCompare(String(b.label || b.id));
  });

  var toolRows = visibleTools.map(function (t) {
    var visOverride = "";
    try { visOverride = providers.compat.lsGet("eli_menuvis_" + (t.catalog && t.catalog.id || t.id)) || ""; } catch (e) {}
    var hidden = visOverride === "hide" || (visOverride !== "show" && !!(t.catalog && t.catalog.hidden));
    return {
      kind: "tool",
      id: t.id,
      label: t.label || t.id,
      icon: (t.catalog && t.catalog.icon) || "🛠️",
      category: (t.catalog && t.catalog.category) || "Other",
      releasedAt: t.releasedAt || t.installedAt || null,
      tier: t.tier || "demand",
      isV3: !!(t.engine || t.view || (t.advertises && t.advertises.tile)),
      enabled: !t.disabled,
      hidden: hidden,
      core: !!(t.catalog && t.catalog.core),
    };
  });

  // Cross-reference data stamps against manifest entries for label + filename.
  var manifest = null;
  try {
    if (providers.tools.getCachedManifest) manifest = await providers.tools.getCachedManifest();
  } catch (e) {}
  var manifestById = {};
  if (manifest && Array.isArray(manifest.tools)) {
    manifest.tools.forEach(function (e) { manifestById[e.id] = e; });
  }

  // Friendly labels for known proprietary libraries. Recognizes both
  // canonical (snake_case) AND legacy (camelCase) IDs since earlier
  // versions of the install path produced the camelCase form.
  var KNOWN_LIB_LABELS = {
    "__data_bd_templates":     "Build Draft Templates",
    "__data_bdTemplates":      "Build Draft Templates",
    "__data_playbooks":        "Negotiation Playbooks",
    "__data_riskRules":        "Risk Rules Library",
    "__data_risk_rules":       "Risk Rules Library",
    "__data_requesters":       "Requesters Directory",
    "__data_requesters_enc":   "Requesters Directory",
    "__data_templates":        "Document Templates",
    "__data_team_commentary":  "Team Commentary",
    "__data_teamCommentary":   "Team Commentary",
  };
  // Aliases from legacy (camelCase) → canonical (snake_case) ids. When
  // the user's installed stamp is camelCase but the manifest now uses
  // snake_case (or vice versa), we cross-ref under both keys so the row
  // gets a `manifestEntry` and shows as cdnTracked.
  var ID_ALIASES = {
    "__data_bdTemplates":    "__data_bd_templates",
    "__data_riskRules":      "__data_risk_rules",
    "__data_teamCommentary": "__data_team_commentary",
    "__data_requesters":     "__data_requesters_enc",
  };

  var dataRows = dataBundles.sort(function (a, b) {
    return String(a.id).localeCompare(String(b.id));
  }).map(function (d) {
    // Try direct id, then alias lookup so legacy camelCase installs
    // still match snake_case manifest entries.
    var entry = manifestById[d.id] || (ID_ALIASES[d.id] && manifestById[ID_ALIASES[d.id]]) || null;
    var label = (entry && entry.label)
              || KNOWN_LIB_LABELS[d.id]
              || d.id.replace(/^__data_/, "").replace(/^_/, "");
    var cdnTracked = !!(entry && entry.filename);
    // Encrypted = source flag OR manifest says encrypted OR id maps to
    // a known encrypted library. Catches legacy installs that didn't
    // record the source field properly.
    var fromEncrypted = d.source === "encrypted_library"
      || !!(entry && entry.encrypted)
      || /^__data_(bd_templates|bdTemplates|playbooks|riskRules|risk_rules|templates|requesters|requesters_enc|team_commentary|teamCommentary)$/.test(d.id);
    return {
      kind: "data",
      id: d.id,
      label: label,
      icon: fromEncrypted ? "🔐" : (cdnTracked ? "📚" : "🔒"),
      sourceTag: fromEncrypted ? "ENCRYPTED" : (cdnTracked ? "CDN" : "LOCAL"),
      category: "Data Libraries",
      releasedAt: d.releasedAt,
      fetchedAt: d.fetchedAt,
      source: d.source,
      cdnTracked: cdnTracked,
      fromEncrypted: fromEncrypted,
      manifestEntry: entry,
    };
  });

  var byCategory = {};
  toolRows.forEach(function (r) {
    if (!byCategory[r.category]) byCategory[r.category] = [];
    byCategory[r.category].push(r);
  });
  if (dataRows.length) {
    byCategory["Data Libraries"] = dataRows;
  }

  return {
    items: toolRows.concat(dataRows),
    byCategory: byCategory,
    overview:
      toolRows.length + " tool" + (toolRows.length === 1 ? "" : "s") +
      " · " + dataRows.length + " data lib" + (dataRows.length === 1 ? "" : "s"),
    toolCount: toolRows.length,
    dataCount: dataRows.length,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: (window.eli && window.eli.tools && window.eli.tools._loaded && window.eli.tools._loaded.tool_manager && window.eli.tools._loaded.tool_manager.releasedAt) || "unknown",
      docHash: null,
      timestamp: Date.now(),
    },
  };
}

view.renderReinstallPicker:
function renderReinstallPicker(opts) {
  var rows = opts.rows || []; // [{id, label, kind, icon, cdnTracked}]
  var onConfirm = opts.onConfirm || function () {};
  var onCancel = opts.onCancel || function () {};
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Dialog primitive missing", "err");
    return;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Group by kind for readability.
  var groups = { tools: [], data: [], local: [] };
  rows.forEach(function (r) {
    if (r.kind === "data" && r.cdnTracked === false) groups.local.push(r);
    else if (r.kind === "data") groups.data.push(r);
    else groups.tools.push(r);
  });

  function _itemRow(r, disabled) {
    var cb = disabled
      ? '<span class="_eli3_tm_pick_row_lock" title="Re-import required">🔒</span>'
      : '<input type="checkbox" data-eli-tm-pick="' + _esc(r.id) + '" checked>';
    var icon = r.icon || (r.kind === "data" ? "📚" : "🛠️");
    return '<label class="_eli3_tm_pick_row' + (disabled ? ' _eli3_tm_pick_row_disabled' : '') + '">' +
      cb +
      '<span class="_eli3_tm_pick_row_icon">' + _esc(icon) + '</span>' +
      '<span class="_eli3_tm_pick_row_label">' + _esc(r.label) + '</span>' +
      '<span class="_eli3_tm_pick_id">' + _esc(r.id) + '</span>' +
    '</label>';
  }
  function _section(title, sub, items, disabled) {
    if (!items.length) return "";
    return '<div class="_eli3_tm_pick_section">' +
      '<div class="_eli3_tm_pick_section_head">' +
        '<span class="_eli3_tm_pick_section_title">' + _esc(title) + '</span>' +
        '<span class="_eli3_tm_pick_section_count">' + items.length + '</span>' +
      '</div>' +
      (sub ? '<div class="_eli3_tm_pick_section_sub">' + _esc(sub) + '</div>' : "") +
      items.map(function (r) { return _itemRow(r, disabled); }).join("") +
    '</div>';
  }

  var bodyHtml =
    '<div class="_eli3_tm_pick_intro">' +
      'Forces a fresh download from CDN for everything you tick. User settings + IDB stats are preserved.' +
    '</div>' +
    '<div class="_eli3_tm_pick_quickactions">' +
      '<button class="_eli3_tm_pick_quick" id="_eli3_tm_pick_all">Select all</button>' +
      '<button class="_eli3_tm_pick_quick" id="_eli3_tm_pick_none">Clear all</button>' +
    '</div>' +
    _section("Tools", null, groups.tools, false) +
    _section("Data Libraries", null, groups.data, false) +
    _section("Local Libraries", "Manually imported — refresh via 📥 Upload File", groups.local, true);

  showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_dialog_wide _eli3_tm_pick_dialog",
    icon: "↺",
    title: "Force Reinstall",
    body: bodyHtml,
    primary: {
      label: "Reinstall selected",
      onclick: function (e, ov) {
        var picks = [];
        ov.querySelectorAll("[data-eli-tm-pick]:checked").forEach(function (cb) {
          picks.push(cb.getAttribute("data-eli-tm-pick"));
        });
        if (ov.parentNode) ov.parentNode.removeChild(ov);
        onConfirm(picks);
      },
    },
    secondary: { label: "Cancel", onclick: function () { onCancel(); } },
    onMount: function (overlay) {
      overlay.querySelector("#_eli3_tm_pick_all").onclick = function () {
        overlay.querySelectorAll("[data-eli-tm-pick]").forEach(function (cb) { cb.checked = true; });
      };
      overlay.querySelector("#_eli3_tm_pick_none").onclick = function () {
        overlay.querySelectorAll("[data-eli-tm-pick]").forEach(function (cb) { cb.checked = false; });
      };
    },
  });
}

view.renderManagerPanel:
function renderManagerPanel(opts) {
  var result = opts.result || {};
  var rows = result.items || [];
  var byCategory = result.byCategory || {};
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var onToggleEnabled = opts.onToggleEnabled || function () {};
  var onToggleHidden  = opts.onToggleHidden  || function () {};
  var onForceReinstall = opts.onForceReinstall || function () {};
  var onExport = opts.onExport || function () {};
  var onUninstall = opts.onUninstall || function () {};
  var onCheckUpdates = opts.onCheckUpdates || function () {};
  var onImport = opts.onImport || function () {};
  var onClose = opts.onClose || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function _shortTs(iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    var hours = d.getHours();
    var ampm = hours >= 12 ? "pm" : "am";
    hours = hours % 12 || 12;
    var mins = ("0" + d.getMinutes()).slice(-2);
    return months[d.getMonth()] + " " + d.getDate() + " - " + hours + ":" + mins + ampm;
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_tm_root";

  // Header bar with back arrow + title + actions
  var bar = document.createElement("div");
  bar.className = "_eli3_tm_bar";
  bar.innerHTML =
    '<button class="_eli3_tm_back" title="Back">←</button>' +
    '<div class="_eli3_tm_title">🧩 Tool Manager</div>' +
    '<div class="_eli3_tm_overview">' + _esc(result.overview || "") + '</div>';
  bar.querySelector("._eli3_tm_back").onclick = onClose;
  root.appendChild(bar);

  // Action row at top
  var actions = document.createElement("div");
  actions.className = "_eli3_tm_actions";
  function _btn(label, handler, variant) {
    var b = document.createElement("button");
    b.className = "_eli3_tm_action_btn" + (variant ? " " + variant : "");
    b.textContent = label;
    b.onclick = handler;
    return b;
  }
  actions.appendChild(_btn("🔄 Check for Updates", onCheckUpdates));
  actions.appendChild(_btn("↺ Force Reinstall", opts.onReinstallAll || function () {}, "_eli3_tm_action_secondary"));
  // Manual install: paste/drop a single tool OR data bundle JSON. Type is
  // auto-detected. Useful when CDN auto-update is stuck or for offline
  // installs / pre-release testing.
  actions.appendChild(_btn("📥 Upload File", onImport, "_eli3_tm_action_secondary"));
  root.appendChild(actions);

  // Category-grouped list
  var listWrap = document.createElement("div");
  listWrap.className = "_eli3_tm_list";
  var categories = Object.keys(byCategory).sort();
  if (!categories.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_tm_empty";
    empty.textContent = "No tools installed.";
    listWrap.appendChild(empty);
  } else {
    categories.forEach(function (cat) {
      var head = document.createElement("div");
      head.className = "_eli3_tm_cat_head";
      head.textContent = cat;
      listWrap.appendChild(head);
      byCategory[cat].forEach(function (t) {
        listWrap.appendChild(_renderRow(t));
      });
    });
  }
  root.appendChild(listWrap);

  function _renderRow(t) {
    var r = document.createElement("div");
    r.className = "_eli3_tm_row" + (t.enabled === false ? " _eli3_tm_row_disabled" : "");
    var isData = t.kind === "data";
    var rightSide = isData
      // Data rows: kebab only (no toggle — data isn't disable-able).
      ? '<button class="_eli3_tm_kebab" data-eli-tm-kebab="' + _esc(t.id) + '" title="More">⋯</button>'
      : '<label class="_eli3_tm_toggle" title="Enable / disable">' +
          '<input type="checkbox" data-eli-tm-enable="' + _esc(t.id) + '"' + (t.enabled ? " checked" : "") + '>' +
          '<span class="_eli3_tm_toggle_slider"></span>' +
        '</label>' +
        '<button class="_eli3_tm_kebab" data-eli-tm-kebab="' + _esc(t.id) + '" title="More">⋯</button>';
    // Two destructive actions, distinct intent:
    //   ↺ Force re-install — clears + re-syncs from CDN immediately
    //   🗑 Uninstall       — clears only; user clicks Check for Updates
    //                         later to bring it back (or re-import for
    //                         local-only libraries).
    var drawerActions = isData
      ? '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-reinstall="' + _esc(t.id) + '">↺ Force re-install</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_danger" data-eli-tm-uninstall="' + _esc(t.id) + '">🗑 Uninstall</button>'
      : '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-vis="' + _esc(t.id) + '">' +
          (t.hidden ? "👁 Show on dashboard" : "🚫 Hide from dashboard") +
        '</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-reinstall="' + _esc(t.id) + '">↺ Force re-install</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-export="' + _esc(t.id) + '">📤 Export</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_danger" data-eli-tm-uninstall="' + _esc(t.id) + '">🗑 Uninstall</button>';
    var labelTag = isData
      ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_data">DATA</span>' +
        (t.sourceTag === "ENCRYPTED" ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_encrypted">ENCRYPTED</span>'
         : t.sourceTag === "LOCAL"   ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_local">LOCAL</span>'
         : '')
      : ((!t.isV3 ? ' <span class="_eli3_tm_row_tag">V2</span>' : '') +
         (t.core ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_core">CORE</span>' : ''));
    r.innerHTML =
      '<div class="_eli3_tm_row_main">' +
        '<div class="_eli3_tm_row_icon">' + _esc(t.icon) + '</div>' +
        '<div class="_eli3_tm_row_info">' +
          '<div class="_eli3_tm_row_label">' + _esc(t.label) + labelTag + '</div>' +
          '<div class="_eli3_tm_row_meta">' + _esc(t.id) + ' · ' + _shortTs(t.releasedAt) + '</div>' +
        '</div>' +
        '<div class="_eli3_tm_row_actions">' + rightSide + '</div>' +
      '</div>' +
      '<div class="_eli3_tm_row_drawer" data-eli-tm-drawer="' + _esc(t.id) + '" hidden>' +
        drawerActions +
      '</div>';
    r.setAttribute("data-eli-tm-kind", t.kind || "tool");
    return r;
  }

  mount.appendChild(root);

  // Wire row interactions via event delegation on listWrap
  listWrap.addEventListener("change", function (e) {
    var cb = e.target.closest && e.target.closest("[data-eli-tm-enable]");
    if (cb) {
      var id = cb.getAttribute("data-eli-tm-enable");
      onToggleEnabled(id, cb.checked);
    }
  });
  listWrap.addEventListener("click", function (e) {
    var t = e.target;
    var k = t.closest && t.closest("[data-eli-tm-kebab]");
    if (k) {
      var id = k.getAttribute("data-eli-tm-kebab");
      var drawer = listWrap.querySelector('[data-eli-tm-drawer="' + id + '"]');
      if (drawer) drawer.hidden = !drawer.hidden;
      return;
    }
    var v = t.closest && t.closest("[data-eli-tm-vis]");
    if (v) { onToggleHidden(v.getAttribute("data-eli-tm-vis")); return; }
    var r = t.closest && t.closest("[data-eli-tm-reinstall]");
    if (r) { onForceReinstall(r.getAttribute("data-eli-tm-reinstall")); return; }
    var x = t.closest && t.closest("[data-eli-tm-export]");
    if (x) { onExport(x.getAttribute("data-eli-tm-export")); return; }
    var u = t.closest && t.closest("[data-eli-tm-uninstall]");
    if (u) { onUninstall(u.getAttribute("data-eli-tm-uninstall")); return; }
  });
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["tool_manager"];
  var analyze = bundle && bundle._eliEngineFns && bundle._eliEngineFns.analyze;
  var renderManagerPanel = bundle && bundle._eliViewFns && bundle._eliViewFns.renderManagerPanel;
  var renderReinstallPicker = bundle && bundle._eliViewFns && bundle._eliViewFns.renderReinstallPicker;
  if (!analyze || !renderManagerPanel) {
    eli.log.event("tool", "tool_manager_load_failed", { hasEngine: !!analyze, hasView: !!renderManagerPanel });
    return;
  }

  var providers = {
    tools: eli.tools,
    compat: eli.compat,
  };

  function _isDataId(id) { return /^_data_|^__data_/.test(String(id || "")); }

  // Look up a row's metadata from the latest analyze result. Used by
  // uninstall + force-reinstall to detect non-CDN libraries (cdnTracked
  // === false) which can't auto-recover and need re-import instead.
  var _lastResult = null;
  function _findRow(id) {
    if (!_lastResult || !_lastResult.items) return null;
    for (var i = 0; i < _lastResult.items.length; i++) {
      if (_lastResult.items[i].id === id) return _lastResult.items[i];
    }
    return null;
  }

  // Legacy all-or-nothing reinstall — fallback when picker view isn't bundled.
  function _reinstallAllLegacy() {
    eli.events.safeAsync(eli.ui.confirm({
      title: "Re-install everything?",
      message: "Forces a fresh CDN pull for every installed tool AND data library.",
      confirmLabel: "Re-install all",
    }), "tool_manager.reinstall_all.confirm").then(function (ok) {
      if (!ok) return;
      eli.events.safeAsync(
        Promise.all([eli.tools.list(), eli.tools.listData ? eli.tools.listData() : Promise.resolve([])]),
        "tool_manager.reinstall_all.list"
      ).then(function (rs) {
        var toolIds = (rs[0] || [])
          .filter(function (t) { return t && t.id && String(t.id).charAt(0) !== "_"; })
          .map(function (t) { return t.id; });
        var dataIds = (rs[1] || []).map(function (d) { return d.id; });
        var total = toolIds.length + dataIds.length;
        if (!total) { showToast("Nothing installed.", "info"); return; }
        var ops = toolIds.map(function (id) { return eli.tools.uninstall(id).catch(function () {}); })
          .concat(dataIds.map(function (id) { return eli.tools.uninstallData(id).catch(function () {}); }));
        Promise.all(ops).then(function () { return eli.tools.syncFromManifest({ force: true }); })
          .then(function () { showToast("✓ Re-installed " + total + " bundle(s)", "ok"); _show(); });
      });
    });
  }

  function _show() {
    eli.events.safeAsync(analyze({}, providers), "tool_manager.analyze").then(function (result) {
      if (!result) return;
      _lastResult = result;
      renderManagerPanel({
        result: result,
        mount: document.getElementById("_eli3_dashboard_root"),
        onClose: function () {
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
        },
        onToggleEnabled: eli.events.guard(function (id, enabled) {
          var p = enabled ? eli.tools.enable(id) : eli.tools.disable(id);
          eli.events.safeAsync(p, "tool_manager.toggle").then(function () {
            showToast((id) + (enabled ? " enabled" : " disabled"), "ok");
            if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
          });
        }, "tool_manager.toggle"),
        onToggleHidden: eli.events.guard(function (id) {
          var current = eli.compat.lsGet("eli_menuvis_" + id) || "";
          var next = current === "hide" ? "show" : "hide";
          eli.compat.lsSet("eli_menuvis_" + id, next);
          showToast((next === "hide" ? "Hidden " : "Shown ") + id, "ok");
          if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
          _show(); // re-render with updated state
        }, "tool_manager.visibility"),
        onForceReinstall: eli.events.guard(function (id) {
          var isData = _isDataId(id);
          var row = _findRow(id);
          var isLocalLib = isData && row && row.cdnTracked === false;
          // Local (encrypted / manually imported) libraries can't be
          // auto-fetched — route to the import dialog instead.
          if (isLocalLib) {
            eli.events.safeAsync(eli.ui.confirm({
              title: "Re-import " + id + "?",
              message: "This library was imported manually (encrypted credentials or JSON upload). Force-refresh isn't possible from CDN. Want to open the import dialog now?",
              confirmLabel: "Open import",
            }), "tool_manager.local_lib_reimport").then(function (ok) {
              if (!ok) return;
              if (eli.settings && eli.settings.importToken) {
                eli.settings.importToken({ title: "Re-import " + id });
              } else if (eli.settings && eli.settings.importPackage) {
                eli.settings.importPackage();
              } else {
                showToast("Import dialog unavailable.", "err");
              }
            });
            return;
          }
          eli.events.safeAsync(eli.ui.confirm({
            title: "Force re-install " + id + "?",
            message: "Removes the local copy and downloads fresh from CDN.",
          }), "tool_manager.reinstall.confirm").then(function (ok) {
            if (!ok) return;
            var clearStep = isData ? eli.tools.uninstallData(id) : eli.tools.uninstall(id);
            eli.events.safeAsync(
              clearStep.then(function () { return eli.tools.syncFromManifest({ force: true }); }),
              "tool_manager.reinstall"
            ).then(function () {
              showToast("Re-installed " + id, "ok");
              _show();
            });
          });
        }, "tool_manager.reinstall"),
        onExport: eli.events.guard(function (id) {
          eli.events.safeAsync(eli.tools.get(id), "tool_manager.export.get").then(function (b) {
            if (!b) return;
            var json = JSON.stringify({
              schemaVersion: 1,
              releasedAt: b.releasedAt || new Date().toISOString(),
              sections: { jsonTools: [b] },
            }, null, 2);
            try {
              navigator.clipboard.writeText(json);
              showToast("Copied " + id + " JSON to clipboard.", "ok");
            } catch (e) {
              showToast("Clipboard unavailable.", "warn");
            }
          });
        }, "tool_manager.export"),
        onUninstall: eli.events.guard(function (id) {
          var isData = _isDataId(id);
          var row = _findRow(id);
          var isLocalLib = isData && row && row.cdnTracked === false;
          // Plain uninstall (no auto-sync). User clicks Check for Updates
          // to bring CDN-tracked items back. Local libraries lose their
          // data permanently and need re-import to restore.
          var msg = !isData
            ? "Removes the bundle from this device. Click Check for Updates to reinstall."
            : isLocalLib
              ? "⚠️ Wipes ALL rows in this library and removes it from this device. This library was imported manually — Check for Updates can't bring it back. You'll need to re-import the source file (encrypted bundle or JSON)."
              : "Wipes ALL rows in this library and removes it from this device. Click Check for Updates to redownload from CDN.";
          eli.events.safeAsync(eli.ui.confirm({
            title: "Uninstall " + id + "?",
            message: msg,
            confirmLabel: "Uninstall",
          }), "tool_manager.uninstall.confirm").then(function (ok) {
            if (!ok) return;
            var op = isData ? eli.tools.uninstallData(id) : eli.tools.uninstall(id);
            eli.events.safeAsync(op, "tool_manager.uninstall").then(function () {
              showToast("Uninstalled " + id, "ok");
              if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
              _show();
            });
          });
        }, "tool_manager.uninstall"),
        onCheckUpdates: eli.events.guard(function () {
          eli.events.safeAsync(eli.tools.syncFromManifest({ force: true }), "tool_manager.check").then(function (sync) {
            if (eli.dashboard && eli.dashboard.showDownloadsDialog) {
              eli.dashboard.showDownloadsDialog(sync);
            }
          });
        }, "tool_manager.check"),
        onImport: eli.events.guard(function () {
          if (eli.settings && eli.settings.importPackage) eli.settings.importPackage();
        }, "tool_manager.import"),
        onReinstallAll: eli.events.guard(function () {
          if (!renderReinstallPicker) {
            // Fallback to the old all-or-nothing flow if the picker view
            // isn't bundled (e.g. older tool_manager build).
            return _reinstallAllLegacy();
          }
          // Filter: skip kernel-internal tool metadata rows (_meta,
          // __enabled), but KEEP data libraries — their IDs all start
          // with __data_ which is intentional, not internal metadata.
          var rows = (result.items || []).filter(function (r) {
            if (!r || !r.id) return false;
            if (r.kind === "tool" && String(r.id).charAt(0) === "_") return false;
            return true;
          });
          renderReinstallPicker({
            rows: rows,
            onCancel: function () {},
            onConfirm: function (ids) {
              if (!ids || !ids.length) { showToast("Nothing selected.", "info"); return; }
              showToast("Re-installing " + ids.length + " bundle" + (ids.length === 1 ? "" : "s") + "…", "info");
              var ops = ids.map(function (id) {
                return _isDataId(id) ? eli.tools.uninstallData(id).catch(function () {})
                                     : eli.tools.uninstall(id).catch(function () {});
              });
              eli.events.safeAsync(
                Promise.all(ops).then(function () { return eli.tools.syncFromManifest({ force: true }); }),
                "tool_manager.reinstall_picked"
              ).then(function () {
                showToast("✓ Re-installed " + ids.length + " bundle" + (ids.length === 1 ? "" : "s"), "ok");
                if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
                _show();
              });
            },
          });
        }, "tool_manager.reinstall_all"),
      });
    });
  }

  eli.register({
    tile: { app_tool_manager: _show },
  });

  eli.log.event("tool", "tool_manager_initialized", {});
}

jsonTools.css:
/* tool_manager v3 — full-takeover panel. Injected as <style data-tool="tool_manager">. */

._eli3_tm_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  box-sizing: border-box;
  background: #fff;
  overflow: hidden;
}
._eli3_tm_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_tm_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #64748b;
  padding: 0 4px;
}
._eli3_tm_back:hover { color: #1565c0; }
._eli3_tm_title {
  font: 800 16px/1.2 'Georgia', serif;
  color: #0f172a;
  flex: 1;
}
._eli3_tm_overview {
  font: 600 11px/1 'Inter', sans-serif;
  color: #64748b;
  background: #f1f5f9;
  padding: 4px 10px;
}

._eli3_tm_actions {
  display: flex; gap: 8px;
  padding: 12px 14px 0;
}
._eli3_tm_action_btn {
  flex: 1;
  padding: 8px 14px;
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff; border: 1px solid rgba(0,0,0,0.1);
  cursor: pointer;
  transition: transform .12s, box-shadow .12s;
}
._eli3_tm_action_btn:hover { transform: translateY(-1px); box-shadow: 0 4px 10px rgba(21,101,192,0.3); }
._eli3_tm_action_btn._eli3_tm_action_secondary {
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #546e7a; border: 1px solid #b0bec5;
  text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}
._eli3_tm_action_btn._eli3_tm_action_secondary:hover {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0; border-color: #90caf9;
}
._eli3_tm_action_btn._eli3_tm_action_danger {
  background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%);
  color: #fff; border: 1px solid #b91c1c;
}
._eli3_tm_action_btn._eli3_tm_action_danger:hover { transform: translateY(-1px); box-shadow: 0 4px 10px rgba(239,68,68,0.3); }

._eli3_tm_list {
  flex: 1; overflow-y: auto;
  padding: 12px 14px 18px;
}
._eli3_tm_empty {
  text-align: center; padding: 30px 0;
  font: 600 12px/1.4 'Inter', sans-serif; color: #94a3b8;
}
._eli3_tm_cat_head {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #475569;
  margin: 14px 0 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_tm_cat_head:first-child { margin-top: 0; }
._eli3_tm_row {
  border: 1px solid #e2e8f0;
  background: #fff;
  margin-bottom: 6px;
  transition: border-color .15s, background .15s;
}
._eli3_tm_row:hover { border-color: #cbd5e1; }
._eli3_tm_row_disabled { opacity: 0.55; }
._eli3_tm_row_main {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px;
}
._eli3_tm_row_icon { font-size: 22px; line-height: 1; flex-shrink: 0; }
._eli3_tm_row_info { flex: 1; min-width: 0; }
._eli3_tm_row_label {
  font: 700 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_tm_row_tag {
  display: inline-block;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  background: #fef3c7; color: #92400e;
  padding: 2px 5px;
  margin-left: 6px;
  vertical-align: 1px;
}
._eli3_tm_row_tag_core { background: #dbeafe; color: #1e3a8a; }
._eli3_tm_row_tag_data { background: #ede9fe; color: #5b21b6; }
._eli3_tm_row_meta {
  font: 600 10px/1.3 'JetBrains Mono', monospace;
  color: #94a3b8;
  margin-top: 2px;
}
._eli3_tm_row_actions {
  display: flex; gap: 8px; align-items: center;
}
._eli3_tm_kebab {
  background: none; border: none; cursor: pointer;
  font: 700 16px/1 'Inter', sans-serif;
  color: #64748b; padding: 4px 8px;
}
._eli3_tm_kebab:hover { color: #0f172a; }
._eli3_tm_row_drawer[hidden] { display: none; }
._eli3_tm_row_drawer {
  display: flex; flex-wrap: wrap; gap: 6px;
  padding: 10px 12px;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
}
._eli3_tm_row_drawer ._eli3_tm_action_btn { flex: 1 1 auto; min-width: 120px; }

/* Toggle switch (mirrors settings toggle pattern). */
._eli3_tm_toggle { display: inline-flex; align-items: center; cursor: pointer; user-select: none; }
._eli3_tm_toggle input[type="checkbox"] { position: absolute; opacity: 0; pointer-events: none; }
._eli3_tm_toggle_slider {
  width: 32px; height: 16px; background: #cbd5e1;
  position: relative; transition: background 0.15s; display: inline-block;
}
._eli3_tm_toggle_slider::after {
  content: ""; position: absolute; top: 2px; left: 2px;
  width: 12px; height: 12px; background: #fff; transition: left 0.15s;
}
._eli3_tm_toggle input:checked + ._eli3_tm_toggle_slider { background: #1565c0; }
._eli3_tm_toggle input:checked + ._eli3_tm_toggle_slider::after { left: 18px; }

/* Dark mode */

@media (max-width: 380px) {
  ._eli3_tm_action_btn { font-size: 10px; padding: 7px 8px; }
  ._eli3_tm_row_tag { display: none; }
}

/* LOCAL tag — non-CDN, non-encrypted (one-off manual JSON upload). */
._eli3_tm_row_tag_local {
  background: #fef3c7; color: #b45309; border: 1px solid #fbbf24;
}
/* ENCRYPTED tag — installed from a decrypted library envelope. */
._eli3_tm_row_tag_encrypted {
  background: #ede9fe; color: #6d28d9; border: 1px solid #a78bfa;
}

/* =====================================================================
   Force Reinstall picker dialog (premium-tier styling)
   ===================================================================== */
._eli3_tm_pick_dialog ._eli3_dialog_body { padding: 0 !important; }
._eli3_tm_pick_intro {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #475569;
  padding: 14px 18px 10px;
  background: linear-gradient(180deg, #f8fafc 0%, #fff 100%);
  border-bottom: 1px solid #e2e8f0;
}
._eli3_tm_pick_quickactions {
  display: flex; gap: 6px;
  padding: 8px 18px;
  background: #f9fafb;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_tm_pick_quick {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
  padding: 6px 11px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_tm_pick_quick:hover {
  background: #3b82f6; color: #fff; border-color: #1d4ed8;
  transform: translateY(-1px);
  box-shadow: 0 2px 4px rgba(59,130,246,0.3);
}
._eli3_tm_pick_section {
  padding: 12px 18px 8px;
  border-bottom: 1px solid #f1f5f9;
}
._eli3_tm_pick_section:last-of-type { border-bottom: none; }
._eli3_tm_pick_section_head {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 8px;
}
._eli3_tm_pick_section_title {
  font: 800 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.7px;
  color: #0f172a;
}
._eli3_tm_pick_section_count {
  font: 700 10px/1 'Inter', sans-serif;
  /* Lighter royal-blue badge — matches the OARS viewer + Save panel
     headers for cross-UI cohesion. */
  background: #3b82f6; color: #fff;
  padding: 3px 8px;
  border-radius: 10px;
  min-width: 18px;
  text-align: center;
}
._eli3_tm_pick_section_sub {
  font: 400 11px/1.4 'Inter', sans-serif;
  font-style: italic;
  color: #64748b;
  margin-bottom: 6px;
  margin-top: -4px;
}
._eli3_tm_pick_row {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  margin-bottom: 2px;
  font: 500 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
  cursor: pointer;
  border: 1px solid transparent;
  background: #fff;
  transition: all 0.12s;
}
._eli3_tm_pick_row:hover {
  background: #eff6ff;
  border-color: #93c5fd;
}
._eli3_tm_pick_row input[type="checkbox"] {
  flex: 0 0 auto;
  width: 16px; height: 16px;
  accent-color: #3b82f6;
  cursor: pointer;
}
._eli3_tm_pick_row_lock {
  flex: 0 0 16px;
  font-size: 13px;
  text-align: center;
  opacity: 0.6;
}
._eli3_tm_pick_row_icon {
  flex: 0 0 auto;
  font-size: 16px;
  line-height: 1;
}
._eli3_tm_pick_row_label {
  flex: 1 1 auto;
  font-weight: 600;
  color: #0f172a;
  min-width: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
._eli3_tm_pick_id {
  flex: 0 0 auto;
  font: 500 10px/1 monospace;
  color: #64748b;
  background: #f1f5f9;
  padding: 3px 6px;
  border-radius: 3px;
}
._eli3_tm_pick_row_disabled {
  cursor: not-allowed;
  opacity: 0.55;
  background: #fafbfc;
}
._eli3_tm_pick_row_disabled:hover {
  background: #fafbfc;
  border-color: transparent;
}
